/**
 * A Module contains all the code related to this feature to enable tree shaking when this module is
 * not used.
 */
external interface Module {
    var moduleName: ModuleName
    var version: String
    var enterprise: Boolean?
    /**
     * Validation run when registering the module @returns Whether the module is valid or not. If
     * not, a message explaining why it is not valid
     */
    var validate: () -> ModuleValidationResult?
    /**
     * Side effect run when the module is registered, before any grid is created, for module-level
     * setup that must happen at registration time rather than at grid/bean initialisation. Fires on
     * every registration call for the module (it is not deduplicated), so the implementation must
     * be idempotent.
     */
    var onRegister: () -> Unit?
    /**
     * singleton beans which are created once on grid init
     */
    var beans: Array<SingletonBean>?
    /**
     * beans which can have many instances, and can be created/destroyed at any time
     */
    var dynamicBeans: Record<String, JsAny>?
    /**
     * components which can be overridden by the user (e.g. cell renderers). These are the default
     * grid provided versions
     */
    var userComponents: Record<String, ComponentMeta>?
    /**
     * selectors for grid components that can be defined in templates and created by AG stack
     */
    var selectors: Array<ComponentSelector>?
    /**
     * icon mappings *** IMPORTANT NOTE! *** If you change the icons, copy/paste the new content
     * into the docs page custom-icons
     */
    var icons: Record<String, JsAny>?
    var rowModels: Array<RowModelType>?
    var dependsOn: Array<Module>?
    var css: Array<String>?
}

