external interface ModuleValidationInvalidIdResult {
    var isValid: Boolean
    /**
     * The error id explaining the failure. Reported by the registry through the diagnostic
     * pipeline, so that a registration-time failure reaches the error overlay and `issueRaised` as
     * well as the console.
     */
    var errorId: ErrorId
    /**
     * Params for `errorId`'s message, for the ids that take them. Loosely typed as `validate` is
     * not generic.
     */
    var errorParams: JsAny?
    var message: Unit
}

external interface ModuleValidationInvalidResult {
    var isValid: Boolean
    /**
     * Free-text explanation of the failure. Prefer `errorId` where the failure has an error id, so
     * that the registry can route it through the diagnostic pipeline rather than the console alone.
     */
    var message: String
    var errorId: Unit
    var errorParams: Unit
}

